content.content:
1	// 構成案 outline.md を読み、資料の情報とスライドごとのキー・題名・一言・図の説明・発表者ノートを取り出す (計画の KTD13)。
2	// 書式に合わない行は、行番号を付けた誤りにする。最初の誤りで中断せず、すべての誤りを集めてから返す。
3	//
4	// 構成案の書式:
5	//
6	//   # <資料の題名>
7	//
8	//   - 読者: <値>
9	//   - ねらい: <値>
10	//   - 形: <値>
11	//   - 固有名: 一般化する | そのまま書く          (省略できる)
12	//   - Google スライド: <資料の URL>               (省略できる)
13	//   - slide-deck の版: <数.数.数>                 (省略できる)
14	//
15	//   ## <章の名前>                                  (省略できる)
16	//
17	//   ### <キー>: <題名>
18	//   - 図: <図の説明>
19	//     <字下げした行も、図の説明に含める>
20	//   - 一言: <そのスライドで伝えたいことの 1 文>
21	//
22	//   <発表者ノートの段落>
23	//
24	// - 題名の行の前と、資料の情報の行の間には、空行だけを書ける。
25	// - 採否を利用者に質問するスライドは、見出しを ### 【提案】<キー>: <題名> にする (計画の R3)。
26	// - キーは英小文字・数字・ハイフンの 1〜32 文字 (計画の KTD9)。資料の中で 1 つにする。
27	// - スライドの見出しの下には、まず - 図: と - 一言: の行を 1 回ずつ書く。ほかの項目は書けない。
28	// - 箇条書きの後に空行を 1 行以上空けて、発表者ノートの段落を書く。ノートは省略できる。
29	//   ノートは地の文だけにする。- で始まる行と字下げした行は書けない。
30	// - 章は省略できる。章を書くなら、スライドを 1 枚以上入れる。
31	// - 区切りの線 (---) は、どこにも書けない。
32	// - #### 以下の見出しは書けない。
33	
34	/** 構成案の書式の誤り。line は 1 から数えた行番号。 */
35	export interface OutlineError {
36	  line: number;
37	  message: string;
38	}
39	
40	/** 誤りを「<行番号> 行目: <内容>」の形の 1 行にする。 */
41	export function formatOutlineError(e: OutlineError): string {
42	  return `${String(e.line)} 行目: ${e.message}`;
43	}
44	
45	/** 資料の情報の項目「固有名」の値 (計画の R4)。 */
46	export type ProperNouns = "一般化する" | "そのまま書く";
47	
48	const PROPER_NOUNS: readonly ProperNouns[] = ["一般化する", "そのまま書く"];
49	
50	/** 資料の情報の項目「Google スライド」の値。presentationId は URL の /d/ の後の、資料の ID。 */
51	export interface GoogleSlidesRef {
52	  url: string;
53	  presentationId: string;
54	}
55	
56	/** 構成案の先頭の、資料の情報。省略できる項目は、書いていなければ null。 */
57	export interface OutlineInfo {
58	  /** 読者 */
59	  audience: string;
60	  /** ねらい */
61	  purpose: string;
62	  /** 形 */
63	  form: string;
64	  /** 固有名 */
65	  properNouns: ProperNouns | null;
66	  /** Google スライド */
67	  googleSlides: GoogleSlidesRef | null;
68	  /** slide-deck の版 (最後に publish したプラグインの版) */
69	  pluginVersion: string | null;
70	}
71	
72	/** 構成案の 1 枚のスライド。 */
73	export interface OutlineSlide {
74	  key: string;
75	  title: string;
76	  /** 一言 */
77	  takeaway: string;
78	  /** 図の説明。- 図: の行の後の字下げした行も、改行で区切って含める。 */
79	  figure: string;
80	  /** 発表者ノート。段落の中の改行は残し、段落の間は空行 1 つ (\n\n) にする。ノートが無ければ空の文字列。 */
81	  notes: string;
82	  /** スライドが入っている章の名前。章の外なら null。 */
83	  chapter: string | null;
84	  /** 見出しに【提案】が付いているか。 */
85	  proposed: boolean;
86	  /** スライドの見出しの行番号 (1 から数える)。 */
87	  line: number;
88	}
89	
90	/** 読み込んだ構成案。slides の順序は構成案の見出しの順序。 */
91	export interface DeckOutline {
92	  title: string;
93	  info: OutlineInfo;
94	  slides: OutlineSlide[];
95	  /** 【提案】が付いたスライド。build は、これが空でなければ中断する (計画の R3)。 */
96	  proposals: OutlineSlide[];
97	}
98	
99	export type ParseOutlineResult =
100	  | { ok: true; outline: DeckOutline }
101	  | { ok: false; errors: OutlineError[] };
102	
103	/** 資料の情報の項目の名前と、型 OutlineInfo のプロパティの名前の対応。 */
104	export const INFO_LABELS = {
105	  audience: "読者",
106	  purpose: "ねらい",
107	  form: "形",
108	  properNouns: "固有名",
109	  googleSlides: "Google スライド",
110	  pluginVersion: "slide-deck の版",
111	} as const;
112	
113	type InfoField = keyof typeof INFO_LABELS;
114	
115	const INFO_FIELDS = Object.keys(INFO_LABELS) as InfoField[];
116	const REQUIRED_FIELDS: readonly InfoField[] = ["audience", "purpose", "form"];
117	
118	const GOOGLE_SLIDES_URL = /^https:\/\/docs\.google\.com\/presentation\/d\/([A-Za-z0-9_-]+)(?:[/?#]\S*)?$/;
119	const PLUGIN_VERSION = /^\d+\.\d+\.\d+$/;
120	const KEY = /^[a-z0-9-]{1,32}$/;
121	const HEADING = /^(#{1,6})(?:[ \t]+(.*))?$/;
122	const INFO_ITEM = /^- ([^:]+?):[ \t]*(.*)$/;
123	const THEMATIC_BREAK = /^-{3,}[ \t]*$/;
124	const INDENTED = /^[ \t]+\S/;
125	
126	/**
127	 * 資料の情報の項目「Google スライド」の値を検査し、資料の ID を取り出す。
128	 * 形が違えば、誤りの内容を文字列で返す。
129	 */
130	export function parseGoogleSlidesUrl(value: string): GoogleSlidesRef | string {
131	  const m = GOOGLE_SLIDES_URL.exec(value);
132	  const id = m?.[1];
133	  if (id === undefined) {
134	    return `Google スライドの値 ${JSON.stringify(value)} が、https://docs.google.com/presentation/d/<資料の ID> で始まる URL ではない`;
135	  }
136	  return { url: value, presentationId: id };
137	}
138	
139	/** 資料の情報の項目「slide-deck の版」の値を検査する。形が違えば、誤りの内容を文字列で返す。 */
140	export function checkPluginVersion(value: string): string | null {
141	  return PLUGIN_VERSION.test(value)
142	    ? null
143	    : `slide-deck の版の値 ${JSON.stringify(value)} が、数.数.数 (例: 0.1.0) の形ではない`;
144	}
145	
146	/** 構成案のテキストを行に分ける。各行の末尾の \r は除く。 */
147	export function splitLines(text: string): string[] {
148	  return text.split("\n").map((l) => l.replace(/\r$/, ""));
149	}
150	
151	/** 関数 scanHeader の結果。行の位置 (index) は 0 から数える。 */
152	export interface HeaderScan {
153	  /** 資料の題名。題名の行に誤りがあれば null。 */
154	  title: string | null;
155	  /** 資料の情報。題名の行か資料の情報の行に誤りがあれば null。 */
156	  info: OutlineInfo | null;
157	  /** 資料の情報の項目ごとの行の位置。 */
158	  itemIndex: Partial<Record<InfoField, number>>;
159	  /** 資料の情報の最後の項目の行の位置。項目が無ければ null。 */
160	  lastItemIndex: number | null;
161	  /** 題名と資料の情報の後の、最初の見出しの行の位置。見出しが無ければ行の数。 */
162	  end: number;
163	  errors: OutlineError[];
164	}
165	
166	/**
167	 * 題名の行と資料の情報の行を読む。スライドの部分は読まない。
168	 * 関数 parseOutline と、資料の情報の行を書き込むファイル url.ts が使う。
169	 */
170	export function scanHeader(lines: readonly string[]): HeaderScan {
171	  const errors: OutlineError[] = [];
172	  const err = (index: number, message: string): void => {
173	    errors.push({ line: index + 1, message });
174	  };
175	  let i = 0;
176	  while (i < lines.length && (lines[i] ?? "").trim() === "") i++;
177	  let title: string | null = null;
178	  let titleIndex = 0;
179	  const first = lines[i];
180	  if (first === undefined) {
181	    err(0, "題名の行 (# <資料の題名>) が無い");
182	  } else {
183	    titleIndex = i;
184	    const m = HEADING.exec(first);
185	    const heading = m?.[1];
186	    const text = (m?.[2] ?? "").trim();
187	    if (heading === "#" && text !== "") {
188	      title = text;
189	      i++;
190	    } else {
191	      err(i, "最初の行は、題名の行 (# <資料の題名>) にする");
192	      // 題名が空の # の行だけは、題名の行として読み終える。
193	      // ほかの行は、資料の情報の行か、スライドの部分の始まりとして、次の処理で読む
194	      if (heading === "#") i++;
195	    }
196	  }
197	
198	  const values: Partial<Record<InfoField, string>> = {};
199	  const itemIndex: Partial<Record<InfoField, number>> = {};
200	  let lastItemIndex: number | null = null;
201	  for (; i < lines.length; i++) {
202	    const line = lines[i] ?? "";
203	    if (HEADING.test(line)) break;
204	    if (line.trim() === "") continue;
205	    if (THEMATIC_BREAK.test(line)) {
206	      err(i, "区切りの線 (---) は書けない");
207	      continue;
208	    }
209	    const m = INFO_ITEM.exec(line);
210	    const label = m?.[1];
211	    if (m === null || label === undefined) {
212	      err(i, "資料の情報の行は、- <項目>: <値> の形にする");
213	      continue;
214	    }
215	    const field = INFO_FIELDS.find((f) => INFO_LABELS[f] === label);
216	    if (field === undefined) {
217	      const names = INFO_FIELDS.map((f) => INFO_LABELS[f]).join("・");
218	      err(i, `資料の情報の項目 ${JSON.stringify(label)} は使えない。使える項目は ${names}`);
219	      continue;
220	    }
221	    lastItemIndex = i;
222	    const prev = itemIndex[field];
223	    if (prev !== undefined) {
224	      err(i, `資料の情報の項目 ${label} が ${String(prev + 1)} 行目と ${String(i + 1)} 行目にある。1 回だけ書く`);
225	      continue;
226	    }
227	    itemIndex[field] = i;
228	    const value = (m[2] ?? "").trim();
229	    if (value === "") {
230	      err(i, `資料の情報の項目 ${label} の値が空`);
231	      continue;
232	    }
233	    values[field] = value;
234	  }
235	  const end = i;
236	
237	  for (const f of REQUIRED_FIELDS) {
238	    if (itemIndex[f] === undefined) err(titleIndex, `資料の情報に、項目 ${INFO_LABELS[f]} の行が無い`);
239	  }
240	
241	  let properNouns: ProperNouns | null = null;
242	  const pn = values.properNouns;
243	  if (pn !== undefined) {
244	    const found = PROPER_NOUNS.find((v) => v === pn);
245	    if (found === undefined) {
246	      err(itemIndex.properNouns ?? titleIndex, `固有名の値 ${JSON.stringify(pn)} は使えない。「一般化する」か「そのまま書く」にする`);
247	    } else {
248	      properNouns = found;
249	    }
250	  }
251	  let googleSlides: GoogleSlidesRef | null = null;
252	  if (values.googleSlides !== undefined) {
253	    const r = parseGoogleSlidesUrl(values.googleSlides);
254	    if (typeof r === "string") err(itemIndex.googleSlides ?? titleIndex, r);
255	    else googleSlides = r;
256	  }
257	  const pluginVersion = values.pluginVersion ?? null;
258	  if (pluginVersion !== null) {
259	    const e = checkPluginVersion(pluginVersion);
260	    if (e !== null) err(itemIndex.pluginVersion ?? titleIndex, e);
261	  }
262	
263	  const { audience, purpose, form } = values;
264	  const info =
265	    errors.length === 0 && audience !== undefined && purpose !== undefined && form !== undefined
266	      ? { audience, purpose, form, properNouns, googleSlides, pluginVersion }
267	      : null;
268	  return { title, info, itemIndex, lastItemIndex, end, errors };
269	}
270	
271	/** 読んでいる途中のスライド。 */
272	interface SlideDraft {
273	  /** 見出しの形が正しければキー。誤りがあれば null (誤りは見出しの行で報告済み)。 */
274	  key: string | null;
275	  title: string;
276	  proposed: boolean;
277	  chapter: string | null;
278	  index: number;
279	  figureIndex: number | null;
280	  figure: string[];
281	  takeawayIndex: number | null;
282	  takeaway: string;
283	  /** 箇条書きの最後の項目。字下げした行を、どの項目に含めるかを決める。 */
284	  lastItem: "figure" | "takeaway" | "other" | null;
285	  /** 箇条書きの後の空行を読んだか (読んだら、以降の行はノート)。 */
286	  inNotes: boolean;
287	  paragraphs: string[][];
288	}
289	
290	/** 構成案のテキストを読む。誤りがあれば、すべての誤りを行番号の順に返す。 */
291	export function parseOutline(text: string): ParseOutlineResult {
292	  const lines = splitLines(text);
293	  const header = scanHeader(lines);
294	  const errors: OutlineError[] = [...header.errors];
295	  const err = (index: number, message: string): void => {
296	    errors.push({ line: index + 1, message });
297	  };
298	
299	  const slides: OutlineSlide[] = [];
300	  const keyIndex = new Map<string, number>();
301	  let chapter: { name: string | null; index: number; slides: number } | null = null;
302	  let draft: SlideDraft | null = null;
303	  let slideHeadings = 0;
304	
305	  const finishSlide = (): void => {
306	    if (draft === null) return;
307	    const d = draft;
308	    draft = null;
309	    if (d.figureIndex === null) err(d.index, "スライドに - 図: の行が無い");
310	    if (d.takeawayIndex === null) err(d.index, "スライドに - 一言: の行が無い");
311	    if (d.figureIndex !== null && d.figure.length === 0) err(d.figureIndex, "図の説明が空");
312	    if (d.key === null || d.figureIndex === null || d.takeawayIndex === null) return;
313	    slides.push({
314	      key: d.key,
315	      title: d.title,
316	      takeaway: d.takeaway,
317	      figure: d.figure.join("\n"),
318	      notes: d.paragraphs
319	        .filter((p) => p.length > 0)
320	        .map((p) => p.join("\n"))
321	        .join("\n\n"),
322	      chapter: d.chapter,
323	      proposed: d.proposed,
324	      line: d.index + 1,
325	    });
326	  };
327	  const finishChapter = (): void => {
328	    if (chapter !== null && chapter.slides === 0) err(chapter.index, "章にスライドが 1 枚も無い");
329	    chapter = null;
330	  };
331	
332	  for (let i = header.end; i < lines.length; i++) {
333	    const line = lines[i] ?? "";
334	    const heading = HEADING.exec(line);
335	    if (heading !== null) {
336	      finishSlide();
337	      const level = (heading[1] ?? "").length;
338	      const content = (heading[2] ?? "").trim();
339	      if (level === 1) {
340	        err(i, "題名の行 (# <資料の題名>) は 1 つだけにする");
341	      } else if (level === 2) {
342	        finishChapter();
343	        if (content === "") err(i, "章の見出しの名前が空");
344	        chapter = { name: content === "" ? null : content, index: i, slides: 0 };
345	      } else if (level === 3) {
346	        slideHeadings++;
347	        if (chapter !== null) chapter.slides++;
348	        draft = startSlide(content, i, chapter?.name ?? null, err);
349	        if (draft.key !== null) {
350	          const prev = keyIndex.get(draft.key);
351	          if (prev === undefined) {
352	            keyIndex.set(draft.key, i);
353	          } else {
354	            err(i, `キー ${draft.key} が ${String(prev + 1)} 行目と ${String(i + 1)} 行目にある。キーは資料の中で 1 つにする`);
355	          }
356	        }
357	      } else {
358	        err(i, "見出しは #・##・### だけにする");
359	      }
360	      continue;
361	    }
362	    if (THEMATIC_BREAK.test(line)) {
363	      err(i, "区切りの線 (---) は書けない");
364	      continue;
365	    }
366	    if (draft === null) {
367	      if (line.trim() !== "") err(i, "章の見出しとスライドの見出しの間には、文を書けない");
368	      continue;
369	    }
370	    readSlideLine(draft, line, i, err);
371	  }
372	  finishSlide();
373	  finishChapter();
374	  if (slideHeadings === 0) {
375	    err(Math.min(header.end, lines.length - 1), "スライドの見出し (### <キー>: <題名>) が 1 つも無い");
376	  }
377	
378	  if (errors.length > 0 || header.title === null || header.info === null) {
379	    return { ok: false, errors: errors.sort((a, b) => a.line - b.line) };
380	  }
381	  return {
382	    ok: true,
383	    outline: {
384	      title: header.title,
385	      info: header.info,
386	      slides,
387	      proposals: slides.filter((s) => s.proposed),
388	    },
389	  };
390	}
391	
392	const PROPOSAL = "【提案】";
393	
394	/** スライドの見出しの内容 (### の後) を読み、読んでいる途中のスライドを作る。 */
395	function startSlide(
396	  content: string,
397	  index: number,
398	  chapter: string | null,
399	  err: (index: number, message: string) => void,
400	): SlideDraft {
401	  const proposed = content.startsWith(PROPOSAL);
402	  const rest = proposed ? content.slice(PROPOSAL.length) : content;
403	  const colon = rest.indexOf(":");
404	  let key: string | null = null;
405	  let title = "";
406	  if (colon < 0) {
407	    err(index, "スライドの見出しは ### <キー>: <題名> の形にする");
408	  } else {
409	    const k = rest.slice(0, colon);
410	    title = rest.slice(colon + 1).trim();
411	    if (!KEY.test(k)) {
412	      err(
413	        index,
414	        `キー ${JSON.stringify(k)} は使えない。キーは英小文字・数字・ハイフンの 1〜32 文字にする`,
415	      );
416	    } else if (title === "") {
417	      err(index, `スライド ${k} の題名が空`);
418	    } else {
419	      key = k;
420	    }
421	  }
422	  return {
423	    key,
424	    title,
425	    proposed,
426	    chapter,
427	    index,
428	    figureIndex: null,
429	    figure: [],
430	    takeawayIndex: null,
431	    takeaway: "",
432	    lastItem: null,
433	    inNotes: false,
434	    paragraphs: [],
435	  };
436	}
437	
438	const SLIDE_ITEM = /^- (図|一言):[ \t]*(.*)$/;
439	
440	/** スライドの見出しの後の 1 行を読む。 */
441	function readSlideLine(
442	  d: SlideDraft,
443	  line: string,
444	  index: number,
445	  err: (index: number, message: string) => void,
446	): void {
447	  const blank = line.trim() === "";
448	  if (!d.inNotes) {
449	    const hasItems = d.lastItem !== null;
450	    if (blank) {
451	      // 箇条書きの後の空行から、ノートが始まる。見出しと箇条書きの間の空行は読み飛ばす
452	      if (hasItems) d.inNotes = true;
453	      return;
454	    }
455	    if (line.startsWith("- ")) {
456	      readSlideItem(d, line, index, err);
457	      return;
458	    }
459	    if (INDENTED.test(line)) {
460	      if (d.lastItem === "figure") d.figure.push(line.trimEnd());
461	      else if (d.lastItem === "takeaway") err(index, "一言は 1 行で書く");
462	      else if (d.lastItem === null) err(index, "字下げした行は、- 図: の行の後にだけ書ける");
463	      // d.lastItem が "other" なら、その項目の行で誤りを報告済み
464	      return;
465	    }
466	    if (hasItems) err(index, "発表者ノートの前に、空行を入れる");
467	    d.inNotes = true;
468	  }
469	  if (blank) {
470	    if ((d.paragraphs.at(-1)?.length ?? 0) > 0) d.paragraphs.push([]);
471	    return;
472	  }
473	  if (line.startsWith("- ")) {
474	    err(index, "発表者ノートに、- で始まる行は書けない。図の説明は、- 図: の行の後の字下げした行に書く");
475	    return;
476	  }
477	  if (INDENTED.test(line)) {
478	    err(index, "発表者ノートの行は、字下げしない");
479	    return;
480	  }
481	  const last = d.paragraphs.at(-1);
482	  if (last === undefined) d.paragraphs.push([line.trimEnd()]);
483	  else last.push(line.trimEnd());
484	}
485	
486	/** スライドの見出しの下の、- で始まる項目の行を読む。 */
487	function readSlideItem(
488	  d: SlideDraft,
489	  line: string,
490	  index: number,
491	  err: (index: number, message: string) => void,
492	): void {
493	  const m = SLIDE_ITEM.exec(line);
494	  const name = m?.[1];
495	  const value = (m?.[2] ?? "").trim();
496	  if (name === "図") {
497	    d.lastItem = "figure";
498	    if (d.figureIndex !== null) {
499	      err(index, `- 図: の行が ${String(d.figureIndex + 1)} 行目にもある。複数の図は、字下げした行で書く`);
500	      return;
501	    }
502	    d.figureIndex = index;
503	    if (value !== "") d.figure.push(value);
504	    return;
505	  }
506	  if (name === "一言") {
507	    d.lastItem = "takeaway";
508	    if (d.takeawayIndex !== null) {
509	      err(index, `- 一言: の行が ${String(d.takeawayIndex + 1)} 行目にもある`);
510	      return;
511	    }
512	    d.takeawayIndex = index;
513	    if (value === "") err(index, "一言が空");
514	    d.takeaway = value;
515	    return;
516	  }
517	  d.lastItem = "other";
518	  err(index, "スライドの見出しの下の項目は、- 図: と - 一言: だけにする。補足は発表者ノートに書く");
519	}
520

file.content:
// 構成案 outline.md を読み、資料の情報とスライドごとのキー・題名・一言・図の説明・発表者ノートを取り出す (計画の KTD13)。
// 書式に合わない行は、行番号を付けた誤りにする。最初の誤りで中断せず、すべての誤りを集めてから返す。
//
// 構成案の書式:
//
//   # <資料の題名>
//
//   - 読者: <値>
//   - ねらい: <値>
//   - 形: <値>
//   - 固有名: 一般化する | そのまま書く          (省略できる)
//   - Google スライド: <資料の URL>               (省略できる)
//   - slide-deck の版: <数.数.数>                 (省略できる)
//
//   ## <章の名前>                                  (省略できる)
//
//   ### <キー>: <題名>
//   - 図: <図の説明>
//     <字下げした行も、図の説明に含める>
//   - 一言: <そのスライドで伝えたいことの 1 文>
//
//   <発表者ノートの段落>
//
// - 題名の行の前と、資料の情報の行の間には、空行だけを書ける。
// - 採否を利用者に質問するスライドは、見出しを ### 【提案】<キー>: <題名> にする (計画の R3)。
// - キーは英小文字・数字・ハイフンの 1〜32 文字 (計画の KTD9)。資料の中で 1 つにする。
// - スライドの見出しの下には、まず - 図: と - 一言: の行を 1 回ずつ書く。ほかの項目は書けない。
// - 箇条書きの後に空行を 1 行以上空けて、発表者ノートの段落を書く。ノートは省略できる。
//   ノートは地の文だけにする。- で始まる行と字下げした行は書けない。
// - 章は省略できる。章を書くなら、スライドを 1 枚以上入れる。
// - 区切りの線 (---) は、どこにも書けない。
// - #### 以下の見出しは書けない。

/** 構成案の書式の誤り。line は 1 から数えた行番号。 */
export interface OutlineError {
  line: number;
  message: string;
}

/** 誤りを「<行番号> 行目: <内容>」の形の 1 行にする。 */
export function formatOutlineError(e: OutlineError): string {
  return `${String(e.line)} 行目: ${e.message}`;
}

/** 資料の情報の項目「固有名」の値 (計画の R4)。 */
export type ProperNouns = "一般化する" | "そのまま書く";

const PROPER_NOUNS: readonly ProperNouns[] = ["一般化する", "そのまま書く"];

/** 資料の情報の項目「Google スライド」の値。presentationId は URL の /d/ の後の、資料の ID。 */
export interface GoogleSlidesRef {
  url: string;
  presentationId: string;
}

/** 構成案の先頭の、資料の情報。省略できる項目は、書いていなければ null。 */
export interface OutlineInfo {
  /** 読者 */
  audience: string;
  /** ねらい */
  purpose: string;
  /** 形 */
  form: string;
  /** 固有名 */
  properNouns: ProperNouns | null;
  /** Google スライド */
  googleSlides: GoogleSlidesRef | null;
  /** slide-deck の版 (最後に publish したプラグインの版) */
  pluginVersion: string | null;
}

/** 構成案の 1 枚のスライド。 */
export interface OutlineSlide {
  key: string;
  title: string;
  /** 一言 */
  takeaway: string;
  /** 図の説明。- 図: の行の後の字下げした行も、改行で区切って含める。 */
  figure: string;
  /** 発表者ノート。段落の中の改行は残し、段落の間は空行 1 つ (\n\n) にする。ノートが無ければ空の文字列。 */
  notes: string;
  /** スライドが入っている章の名前。章の外なら null。 */
  chapter: string | null;
  /** 見出しに【提案】が付いているか。 */
  proposed: boolean;
  /** スライドの見出しの行番号 (1 から数える)。 */
  line: number;
}

/** 読み込んだ構成案。slides の順序は構成案の見出しの順序。 */
export interface DeckOutline {
  title: string;
  info: OutlineInfo;
  slides: OutlineSlide[];
  /** 【提案】が付いたスライド。build は、これが空でなければ中断する (計画の R3)。 */
  proposals: OutlineSlide[];
}

export type ParseOutlineResult =
  | { ok: true; outline: DeckOutline }
  | { ok: false; errors: OutlineError[] };

/** 資料の情報の項目の名前と、型 OutlineInfo のプロパティの名前の対応。 */
export const INFO_LABELS = {
  audience: "読者",
  purpose: "ねらい",
  form: "形",
  properNouns: "固有名",
  googleSlides: "Google スライド",
  pluginVersion: "slide-deck の版",
} as const;

type InfoField = keyof typeof INFO_LABELS;

const INFO_FIELDS = Object.keys(INFO_LABELS) as InfoField[];
const REQUIRED_FIELDS: readonly InfoField[] = ["audience", "purpose", "form"];

const GOOGLE_SLIDES_URL = /^https:\/\/docs\.google\.com\/presentation\/d\/([A-Za-z0-9_-]+)(?:[/?#]\S*)?$/;
const PLUGIN_VERSION = /^\d+\.\d+\.\d+$/;
const KEY = /^[a-z0-9-]{1,32}$/;
const HEADING = /^(#{1,6})(?:[ \t]+(.*))?$/;
const INFO_ITEM = /^- ([^:]+?):[ \t]*(.*)$/;
const THEMATIC_BREAK = /^-{3,}[ \t]*$/;
const INDENTED = /^[ \t]+\S/;

/**
 * 資料の情報の項目「Google スライド」の値を検査し、資料の ID を取り出す。
 * 形が違えば、誤りの内容を文字列で返す。
 */
export function parseGoogleSlidesUrl(value: string): GoogleSlidesRef | string {
  const m = GOOGLE_SLIDES_URL.exec(value);
  const id = m?.[1];
  if (id === undefined) {
    return `Google スライドの値 ${JSON.stringify(value)} が、https://docs.google.com/presentation/d/<資料の ID> で始まる URL ではない`;
  }
  return { url: value, presentationId: id };
}

/** 資料の情報の項目「slide-deck の版」の値を検査する。形が違えば、誤りの内容を文字列で返す。 */
export function checkPluginVersion(value: string): string | null {
  return PLUGIN_VERSION.test(value)
    ? null
    : `slide-deck の版の値 ${JSON.stringify(value)} が、数.数.数 (例: 0.1.0) の形ではない`;
}

/** 構成案のテキストを行に分ける。各行の末尾の \r は除く。 */
export function splitLines(text: string): string[] {
  return text.split("\n").map((l) => l.replace(/\r$/, ""));
}

/** 関数 scanHeader の結果。行の位置 (index) は 0 から数える。 */
export interface HeaderScan {
  /** 資料の題名。題名の行に誤りがあれば null。 */
  title: string | null;
  /** 資料の情報。題名の行か資料の情報の行に誤りがあれば null。 */
  info: OutlineInfo | null;
  /** 資料の情報の項目ごとの行の位置。 */
  itemIndex: Partial<Record<InfoField, number>>;
  /** 資料の情報の最後の項目の行の位置。項目が無ければ null。 */
  lastItemIndex: number | null;
  /** 題名と資料の情報の後の、最初の見出しの行の位置。見出しが無ければ行の数。 */
  end: number;
  errors: OutlineError[];
}

/**
 * 題名の行と資料の情報の行を読む。スライドの部分は読まない。
 * 関数 parseOutline と、資料の情報の行を書き込むファイル url.ts が使う。
 */
export function scanHeader(lines: readonly string[]): HeaderScan {
  const errors: OutlineError[] = [];
  const err = (index: number, message: string): void => {
    errors.push({ line: index + 1, message });
  };
  let i = 0;
  while (i < lines.length && (lines[i] ?? "").trim() === "") i++;
  let title: string | null = null;
  let titleIndex = 0;
  const first = lines[i];
  if (first === undefined) {
    err(0, "題名の行 (# <資料の題名>) が無い");
  } else {
    titleIndex = i;
    const m = HEADING.exec(first);
    const heading = m?.[1];
    const text = (m?.[2] ?? "").trim();
    if (heading === "#" && text !== "") {
      title = text;
      i++;
    } else {
      err(i, "最初の行は、題名の行 (# <資料の題名>) にする");
      // 題名が空の # の行だけは、題名の行として読み終える。
      // ほかの行は、資料の情報の行か、スライドの部分の始まりとして、次の処理で読む
      if (heading === "#") i++;
    }
  }

  const values: Partial<Record<InfoField, string>> = {};
  const itemIndex: Partial<Record<InfoField, number>> = {};
  let lastItemIndex: number | null = null;
  for (; i < lines.length; i++) {
    const line = lines[i] ?? "";
    if (HEADING.test(line)) break;
    if (line.trim() === "") continue;
    if (THEMATIC_BREAK.test(line)) {
      err(i, "区切りの線 (---) は書けない");
      continue;
    }
    const m = INFO_ITEM.exec(line);
    const label = m?.[1];
    if (m === null || label === undefined) {
      err(i, "資料の情報の行は、- <項目>: <値> の形にする");
      continue;
    }
    const field = INFO_FIELDS.find((f) => INFO_LABELS[f] === label);
    if (field === undefined) {
      const names = INFO_FIELDS.map((f) => INFO_LABELS[f]).join("・");
      err(i, `資料の情報の項目 ${JSON.stringify(label)} は使えない。使える項目は ${names}`);
      continue;
    }
    lastItemIndex = i;
    const prev = itemIndex[field];
    if (prev !== undefined) {
      err(i, `資料の情報の項目 ${label} が ${String(prev + 1)} 行目と ${String(i + 1)} 行目にある。1 回だけ書く`);
      continue;
    }
    itemIndex[field] = i;
    const value = (m[2] ?? "").trim();
    if (value === "") {
      err(i, `資料の情報の項目 ${label} の値が空`);
      continue;
    }
    values[field] = value;
  }
  const end = i;

  for (const f of REQUIRED_FIELDS) {
    if (itemIndex[f] === undefined) err(titleIndex, `資料の情報に、項目 ${INFO_LABELS[f]} の行が無い`);
  }

  let properNouns: ProperNouns | null = null;
  const pn = values.properNouns;
  if (pn !== undefined) {
    const found = PROPER_NOUNS.find((v) => v === pn);
    if (found === undefined) {
      err(itemIndex.properNouns ?? titleIndex, `固有名の値 ${JSON.stringify(pn)} は使えない。「一般化する」か「そのまま書く」にする`);
    } else {
      properNouns = found;
    }
  }
  let googleSlides: GoogleSlidesRef | null = null;
  if (values.googleSlides !== undefined) {
    const r = parseGoogleSlidesUrl(values.googleSlides);
    if (typeof r === "string") err(itemIndex.googleSlides ?? titleIndex, r);
    else googleSlides = r;
  }
  const pluginVersion = values.pluginVersion ?? null;
  if (pluginVersion !== null) {
    const e = checkPluginVersion(pluginVersion);
    if (e !== null) err(itemIndex.pluginVersion ?? titleIndex, e);
  }

  const { audience, purpose, form } = values;
  const info =
    errors.length === 0 && audience !== undefined && purpose !== undefined && form !== undefined
      ? { audience, purpose, form, properNouns, googleSlides, pluginVersion }
      : null;
  return { title, info, itemIndex, lastItemIndex, end, errors };
}

/** 読んでいる途中のスライド。 */
interface SlideDraft {
  /** 見出しの形が正しければキー。誤りがあれば null (誤りは見出しの行で報告済み)。 */
  key: string | null;
  title: string;
  proposed: boolean;
  chapter: string | null;
  index: number;
  figureIndex: number | null;
  figure: string[];
  takeawayIndex: number | null;
  takeaway: string;
  /** 箇条書きの最後の項目。字下げした行を、どの項目に含めるかを決める。 */
  lastItem: "figure" | "takeaway" | "other" | null;
  /** 箇条書きの後の空行を読んだか (読んだら、以降の行はノート)。 */
  inNotes: boolean;
  paragraphs: string[][];
}

/** 構成案のテキストを読む。誤りがあれば、すべての誤りを行番号の順に返す。 */
export function parseOutline(text: string): ParseOutlineResult {
  const lines = splitLines(text);
  const header = scanHeader(lines);
  const errors: OutlineError[] = [...header.errors];
  const err = (index: number, message: string): void => {
    errors.push({ line: index + 1, message });
  };

  const slides: OutlineSlide[] = [];
  const keyIndex = new Map<string, number>();
  let chapter: { name: string | null; index: number; slides: number } | null = null;
  let draft: SlideDraft | null = null;
  let slideHeadings = 0;

  const finishSlide = (): void => {
    if (draft === null) return;
    const d = draft;
    draft = null;
    if (d.figureIndex === null) err(d.index, "スライドに - 図: の行が無い");
    if (d.takeawayIndex === null) err(d.index, "スライドに - 一言: の行が無い");
    if (d.figureIndex !== null && d.figure.length === 0) err(d.figureIndex, "図の説明が空");
    if (d.key === null || d.figureIndex === null || d.takeawayIndex === null) return;
    slides.push({
      key: d.key,
      title: d.title,
      takeaway: d.takeaway,
      figure: d.figure.join("\n"),
      notes: d.paragraphs
        .filter((p) => p.length > 0)
        .map((p) => p.join("\n"))
        .join("\n\n"),
      chapter: d.chapter,
      proposed: d.proposed,
      line: d.index + 1,
    });
  };
  const finishChapter = (): void => {
    if (chapter !== null && chapter.slides === 0) err(chapter.index, "章にスライドが 1 枚も無い");
    chapter = null;
  };

  for (let i = header.end; i < lines.length; i++) {
    const line = lines[i] ?? "";
    const heading = HEADING.exec(line);
    if (heading !== null) {
      finishSlide();
      const level = (heading[1] ?? "").length;
      const content = (heading[2] ?? "").trim();
      if (level === 1) {
        err(i, "題名の行 (# <資料の題名>) は 1 つだけにする");
      } else if (level === 2) {
        finishChapter();
        if (content === "") err(i, "章の見出しの名前が空");
        chapter = { name: content === "" ? null : content, index: i, slides: 0 };
      } else if (level === 3) {
        slideHeadings++;
        if (chapter !== null) chapter.slides++;
        draft = startSlide(content, i, chapter?.name ?? null, err);
        if (draft.key !== null) {
          const prev = keyIndex.get(draft.key);
          if (prev === undefined) {
            keyIndex.set(draft.key, i);
          } else {
            err(i, `キー ${draft.key} が ${String(prev + 1)} 行目と ${String(i + 1)} 行目にある。キーは資料の中で 1 つにする`);
          }
        }
      } else {
        err(i, "見出しは #・##・### だけにする");
      }
      continue;
    }
    if (THEMATIC_BREAK.test(line)) {
      err(i, "区切りの線 (---) は書けない");
      continue;
    }
    if (draft === null) {
      if (line.trim() !== "") err(i, "章の見出しとスライドの見出しの間には、文を書けない");
      continue;
    }
    readSlideLine(draft, line, i, err);
  }
  finishSlide();
  finishChapter();
  if (slideHeadings === 0) {
    err(Math.min(header.end, lines.length - 1), "スライドの見出し (### <キー>: <題名>) が 1 つも無い");
  }

  if (errors.length > 0 || header.title === null || header.info === null) {
    return { ok: false, errors: errors.sort((a, b) => a.line - b.line) };
  }
  return {
    ok: true,
    outline: {
      title: header.title,
      info: header.info,
      slides,
      proposals: slides.filter((s) => s.proposed),
    },
  };
}

const PROPOSAL = "【提案】";

/** スライドの見出しの内容 (### の後) を読み、読んでいる途中のスライドを作る。 */
function startSlide(
  content: string,
  index: number,
  chapter: string | null,
  err: (index: number, message: string) => void,
): SlideDraft {
  const proposed = content.startsWith(PROPOSAL);
  const rest = proposed ? content.slice(PROPOSAL.length) : content;
  const colon = rest.indexOf(":");
  let key: string | null = null;
  let title = "";
  if (colon < 0) {
    err(index, "スライドの見出しは ### <キー>: <題名> の形にする");
  } else {
    const k = rest.slice(0, colon);
    title = rest.slice(colon + 1).trim();
    if (!KEY.test(k)) {
      err(
        index,
        `キー ${JSON.stringify(k)} は使えない。キーは英小文字・数字・ハイフンの 1〜32 文字にする`,
      );
    } else if (title === "") {
      err(index, `スライド ${k} の題名が空`);
    } else {
      key = k;
    }
  }
  return {
    key,
    title,
    proposed,
    chapter,
    index,
    figureIndex: null,
    figure: [],
    takeawayIndex: null,
    takeaway: "",
    lastItem: null,
    inNotes: false,
    paragraphs: [],
  };
}

const SLIDE_ITEM = /^- (図|一言):[ \t]*(.*)$/;

/** スライドの見出しの後の 1 行を読む。 */
function readSlideLine(
  d: SlideDraft,
  line: string,
  index: number,
  err: (index: number, message: string) => void,
): void {
  const blank = line.trim() === "";
  if (!d.inNotes) {
    const hasItems = d.lastItem !== null;
    if (blank) {
      // 箇条書きの後の空行から、ノートが始まる。見出しと箇条書きの間の空行は読み飛ばす
      if (hasItems) d.inNotes = true;
      return;
    }
    if (line.startsWith("- ")) {
      readSlideItem(d, line, index, err);
      return;
    }
    if (INDENTED.test(line)) {
      if (d.lastItem === "figure") d.figure.push(line.trimEnd());
      else if (d.lastItem === "takeaway") err(index, "一言は 1 行で書く");
      else if (d.lastItem === null) err(index, "字下げした行は、- 図: の行の後にだけ書ける");
      // d.lastItem が "other" なら、その項目の行で誤りを報告済み
      return;
    }
    if (hasItems) err(index, "発表者ノートの前に、空行を入れる");
    d.inNotes = true;
  }
  if (blank) {
    if ((d.paragraphs.at(-1)?.length ?? 0) > 0) d.paragraphs.push([]);
    return;
  }
  if (line.startsWith("- ")) {
    err(index, "発表者ノートに、- で始まる行は書けない。図の説明は、- 図: の行の後の字下げした行に書く");
    return;
  }
  if (INDENTED.test(line)) {
    err(index, "発表者ノートの行は、字下げしない");
    return;
  }
  const last = d.paragraphs.at(-1);
  if (last === undefined) d.paragraphs.push([line.trimEnd()]);
  else last.push(line.trimEnd());
}

/** スライドの見出しの下の、- で始まる項目の行を読む。 */
function readSlideItem(
  d: SlideDraft,
  line: string,
  index: number,
  err: (index: number, message: string) => void,
): void {
  const m = SLIDE_ITEM.exec(line);
  const name = m?.[1];
  const value = (m?.[2] ?? "").trim();
  if (name === "図") {
    d.lastItem = "figure";
    if (d.figureIndex !== null) {
      err(index, `- 図: の行が ${String(d.figureIndex + 1)} 行目にもある。複数の図は、字下げした行で書く`);
      return;
    }
    d.figureIndex = index;
    if (value !== "") d.figure.push(value);
    return;
  }
  if (name === "一言") {
    d.lastItem = "takeaway";
    if (d.takeawayIndex !== null) {
      err(index, `- 一言: の行が ${String(d.takeawayIndex + 1)} 行目にもある`);
      return;
    }
    d.takeawayIndex = index;
    if (value === "") err(index, "一言が空");
    d.takeaway = value;
    return;
  }
  d.lastItem = "other";
  err(index, "スライドの見出しの下の項目は、- 図: と - 一言: だけにする。補足は発表者ノートに書く");
}

